package main

import "fmt"

type Engine struct {
    Power int
}

func (e Engine) Start() string {
    return fmt.Sprintf("заведён на %d л.с.", e.Power)
}

type Car struct {
    Engine
    Brand string
}

func main() {
    c := Car{Engine: Engine{Power: 90}, Brand: "Gopher"}
    fmt.Println(c.Power)
    fmt.Println(c.Start())
}

package main

import "fmt"

type Base struct {
    Label string
}

func (b Base) Show() string {
    return "base: " + b.Label
}

type Box struct {
    Base
    Label string
}

func main() {
    x := Box{Base: Base{Label: "внутри"}, Label: "снаружи"}
    fmt.Println(x.Label)
    fmt.Println(x.Base.Label)
    fmt.Println(x.Show())
}
